const norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const day=s=>new Date(new Date(s||Date.now()).getTime()-5*3600000).toISOString().slice(0,10);
export function createComfort(ctx){
 const {root,esc,money}=ctx;let scope='',attached='',attachedView='',forms={},dirty=new Set(),timer,closing={step:null,cash:'',explanation:''},reviewed={},status='Borrador',catalogQuery='',catalogCategory='',agenda='today';
 const state=()=>ctx.state(),key=()=>{const s=state();return s.user?`charito-draft-v1/${s.user.id}/${s.storeId}/${s.shift?.id||'opening'}`:'';};
 const formKey=f=>`${attachedView}/${f.dataset.form}/${f.dataset.id||''}`;
 const allowed=f=>!f.dataset.form.startsWith('recipe_')&&!f.dataset.form.startsWith('fiscal_')&&!f.dataset.form.startsWith('security_')&&!f.dataset.form.startsWith('control_')&&!['set_user_role','void_sale','login','create_user','update_user','reset_password','upload_photos'].includes(f.dataset.form);
 function collect(){if(!attached||attached!==scope)return;root.querySelectorAll('form[data-form]').forEach(f=>{if(!allowed(f))return;const id=formKey(f);if(!dirty.has(id)&&!f.dataset.request)return;const fields=[...f.elements].filter(e=>e.name&&!e.hasAttribute('data-live-close-value')&&!['password','file','submit','button'].includes(e.type)&&!e.hasAttribute('data-picker-query')).map(e=>({name:e.name,type:e.type,value:e.value,checked:e.type==='checkbox'?false:e.checked}));forms[id]={fields,request:f.dataset.request,payload:f.dataset.payload,version:f.dataset.version};});}
 function persist(){clearTimeout(timer);if(!scope)return;collect();try{sessionStorage.setItem(scope,JSON.stringify({version:1,saved:Date.now(),view:state().view,upgrade:ctx.v2.snapshot(),forms,closing,reviewed}));paintStatus();}catch{status='Borrador sin respaldo: almacenamiento lleno';paintStatus();}}
 function flush(){persist();}
 function hydrate(){const next=key();if(next===scope)return;scope=next;attached='';forms={};dirty.clear();reviewed={};closing={step:null,cash:'',explanation:''};if(!scope)return;try{const raw=JSON.parse(sessionStorage.getItem(scope)||localStorage.getItem(scope)||'null');if(raw?.version===1){forms=raw.forms||{};reviewed=raw.reviewed||{};closing=raw.closing||closing;ctx.v2.restore(raw.upgrade);status='Borrador recuperado';sessionStorage.setItem(scope,JSON.stringify(raw));localStorage.removeItem(scope);}}catch{status='Borrador';}}
 function restoreForms(){root.querySelectorAll('form[data-form]').forEach(f=>{const saved=forms[formKey(f)];if(!saved||!allowed(f))return;if(saved.version&&f.dataset.version&&saved.version!==f.dataset.version){delete forms[formKey(f)];ctx.notice('El pedido cambió en otro dispositivo. Revisa la versión actual antes de editar.',true);return;}for(const v of saved.fields){const el=[...f.elements].find(e=>e.name===v.name&&(e.type===v.type||['hidden','number'].includes(e.type)&&['hidden','number'].includes(v.type)||['due_at','payment_date','occurred_at'].includes(e.name)&&['hidden','datetime-local'].includes(e.type)&&['hidden','datetime-local'].includes(v.type)));if(!el||el.type==='file'||el.type==='password')continue;if(el.type==='checkbox'||el.type==='radio')el.checked=!!v.checked;else el.value=v.value;}if(saved.request){f.dataset.request=saved.request;f.dataset.payload=saved.payload;}dirty.add(formKey(f));});}
 function paintStatus(){const el=root.querySelector('[data-save-status]'),draft=ctx.v2.snapshot(),pending=draft.cart.length>0||dirty.size>0||!!draft.voice?.draft;if(el)el.textContent=status==='Guardando…'?status:pending?'Sin guardar':status.startsWith('Borrador sin respaldo')?status:'';}
 function saving(){status='Guardando…';persist();}
 function committed(f){if(f){delete forms[formKey(f)];dirty.delete(formKey(f));delete f.dataset.request;delete f.dataset.payload;f.reset?.();}status='Guardado en Supabase';clearTimeout(timer);paintStatus();}
 function failed(){status='Borrador · pendiente de guardar';persist();}
 function picker(name,items,optional=false,value='') {return `<span class="product-picker" data-picker data-name="${esc(name)}" data-ids="${items.map(p=>p.id).join(',')}" data-optional="${optional}"><input type="hidden" name="${esc(name)}" value="${esc(value)}"><input type="search" data-picker-query placeholder="Buscar producto…" autocomplete="off" aria-label="Buscar producto" aria-expanded="false"><span class="picker-panel" hidden><select data-picker-category aria-label="Filtrar categoría"><option value="">Todas las categorías</option>${[...new Set(items.map(p=>p.category))].map(c=>`<option>${esc(c)}</option>`).join('')}</select><span data-picker-results></span>${optional?'<button type="button" class="secondary" data-picker-clear>Sin producto de inventario</button>':''}</span></span>`;}
 function pickerResults(el){const ids=el.dataset.ids.split(','),q=norm(el.querySelector('[data-picker-query]').value).split(/\s+/).filter(Boolean),cat=el.querySelector('[data-picker-category]').value,items=state().data.products.filter(p=>ids.includes(p.id)&&(!cat||p.category===cat)&&q.every(w=>norm(`${p.name} ${p.category} ${p.sku}`).includes(w)));el.querySelector('[data-picker-results]').innerHTML=items.slice(0,6).map(p=>`<button type="button" class="picker-result" data-picker-id="${p.id}"><strong>${esc(p.name)}</strong><small>${esc(p.category)} · ${esc(p.unit)} · ${money(p.price)}</small></button>`).join('')+(items.length>6?`<small>${items.length} coincidencias</small>`:!items.length?'<small>No se encontraron productos.</small>':'');}
 function openPicker(el){root.querySelectorAll('.picker-panel').forEach(p=>p.hidden=true);el.querySelector('.picker-panel').hidden=false;el.querySelector('[data-picker-query]').setAttribute('aria-expanded','true');pickerResults(el);}
 function setPicker(el,id){const input=el.querySelector('input[type=hidden]'),p=state().data.products.find(p=>p.id===id);input.value=id;el.querySelector('[data-picker-query]').value=p?`${p.category} · ${p.name}`:'';el.querySelector('[data-picker-query]').setCustomValidity('');el.querySelector('.picker-panel').hidden=true;el.querySelector('[data-picker-query]').setAttribute('aria-expanded','false');input.dispatchEvent(new Event('change',{bubbles:true}));const name=el.dataset.name,qtyName=name==='source_product_id'?'source_qty':name==='output_product_id'?'output_qty':'qty';const qty=el.closest('form')?.elements[qtyName];if(qty&&p)unitWidget(qty,p);}
 function unitWidget(input,p){
  if(!input||!p)return;
  const configured=Number(p.quantity_step),step=Number.isFinite(configured)&&configured>0?configured:(p.unit==='ciento'?.5:1);
  input.step=String(step);
  // HTML validates steps from min, so min=.5 with step=1 rejects whole units.
  // Keep zero for counts and negative bounds for adjustments; positive amounts
  // start at the selected product's smallest presentation.
  if(Number(input.min)>0)input.min=String(step);
  input.inputMode=p.unit==='ciento'?'decimal':'numeric';
  if(input.dataset.unitReady&&p.unit!=='ciento'){
   const wrap=input.closest('.unit-widget');input.type='number';delete input.dataset.unitReady;wrap.replaceWith(input);
  }
  if(p.unit!=='ciento')return;
  if(!input.dataset.unitReady){
   input.dataset.unitReady='1';const span=document.createElement('span');span.className='unit-widget';input.parentNode.insertBefore(span,input);span.append(input);
   span.insertAdjacentHTML('beforeend','<select data-unit-mode aria-label="Unidad de cantidad"><option value="hundred">Cientos</option><option value="pack">Paquetes de 50</option></select><input data-pack-value type="number" inputmode="numeric" step="1" aria-label="Paquetes de 50" hidden>');
  }
  const wrap=input.closest('.unit-widget'),proxy=wrap.querySelector('[data-pack-value]');
  proxy.min=String(Number(input.min||0)*2);
 }
 function setupQuantities(){
  root.querySelectorAll('[data-picker]').forEach(el=>{
   const id=el.querySelector('input[type=hidden]').value,p=state().data.products.find(p=>p.id===id);
   if(p)el.querySelector('[data-picker-query]').value=`${p.category} · ${p.name}`;
   const name=el.dataset.name,qtyName=name==='source_product_id'?'source_qty':name==='output_product_id'?'output_qty':'qty';
   unitWidget(el.closest('form')?.elements[qtyName],p);
  });
  root.querySelectorAll('[data-form="return_workshop"]').forEach(f=>{
   const pending=state().data.returns.find(r=>r.id===f.dataset.id);
   unitWidget(f.elements.qty,state().data.products.find(p=>p.id===pending?.product_id));
  });
 }
 function countProgress(){const inputs=[...root.querySelectorAll('.inventory-table input[name]')];const n=inputs.filter(e=>reviewed[e.name]).length;const el=root.querySelector('[data-review-progress]');if(el)el.textContent=`${n} de ${inputs.length} productos revisados`;}
 function setupCounts(){const table=root.querySelector('.inventory-table');if(!table)return;table.querySelectorAll('input[name]').forEach(input=>{const p=state().data.products.find(p=>p.id===input.name);unitWidget(input,p);const cell=input.closest('tr').querySelector('.countname');if(cell&&!cell.querySelector('[data-reviewed]'))cell.insertAdjacentHTML('beforeend',`<label class="review-check"><input type="checkbox" data-reviewed="${input.name}" ${reviewed[input.name]?'checked':''}> Revisado</label>`);});const filters=root.querySelector('.filters');if(filters&&!root.querySelector('[data-review-progress]'))filters.insertAdjacentHTML('afterend','<div class="review-progress"><strong data-review-progress></strong><button type="button" class="secondary" data-review-visible>Marcar categoría visible revisada</button></div>');countProgress();}
 function catalog(){const items=state().data.products.filter(p=>(!catalogCategory||p.category===catalogCategory)&&norm(`${p.name} ${p.category} ${p.sku}`).includes(norm(catalogQuery)));return `<div class="filters"><label>Buscar en catálogo<input data-catalog-search type="search" value="${esc(catalogQuery)}" placeholder="Nombre o código"></label><label>Categoría<select data-catalog-category><option value="">Todas</option>${[...new Set(state().data.products.map(p=>p.category))].map(c=>`<option ${c===catalogCategory?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div><div data-catalog-results>${catalogResults(items)}</div><div id="product-editor"></div>`;}
 function catalogResults(items){return `<p class="small">${Math.min(items.length,12)} de ${items.length} productos</p><div class="compact-catalog">${items.slice(0,12).map(p=>`<div class="catalog-result"><div><strong>${esc(p.name)}</strong><small>${esc(p.category)} · ${money(p.price)} / ${esc(p.unit)}</small></div>${state().me.role==='admin'?`<button type="button" class="secondary" data-edit="${p.id}">Editar</button>`:''}</div>`).join('')}</div>${!items.length?'<p>No hay coincidencias.</p>':items.length>12?'':''}`;}
 function filterAgenda(){const today=day(),tomorrow=day(Date.now()+86400000);root.querySelectorAll('[data-order-row]').forEach(el=>{const o=state().data.orders.find(o=>o.id===el.dataset.orderRow);if(!o)return;const d=day(o.due_at),match=agenda==='all'||agenda==='today'&&d===today||agenda==='tomorrow'&&d===tomorrow||agenda==='late'&&d<today&&o.status==='pending';if(!match)el.hidden=true;});const empty=root.querySelector('#order-empty');if(empty)empty.hidden=!![...root.querySelectorAll('[data-order-row]')].find(e=>!e.hidden);}
 async function thumbnails(){for(const el of [...root.querySelectorAll('[data-order-row]')].filter(e=>!e.hidden).slice(0,12)){if(el.querySelector('img'))continue;try{const id=el.dataset.orderRow;const list=await ctx.db.storage.from('charito-orders').list(id,{limit:1});const photo=list.data?.find(f=>f.id);if(!photo||!el.isConnected)continue;const signed=await ctx.db.storage.from('charito-orders').createSignedUrl(`${id}/${photo.name}`,300);if(signed.data?.signedUrl&&el.isConnected){const img=document.createElement('img');img.className='order-thumb';img.alt='Referencia del pedido';img.loading='lazy';img.src=signed.data.signedUrl;el.prepend(img);}}catch{}}
 }
 function setupOrders(){const form=root.querySelector('[data-form="new_order"]');if(form&&!form.closest('details')&&!form.closest('dialog')){const card=form.closest('.card'),details=document.createElement('details');details.className='new-order';if(form.elements.customer_name?.value||form.elements.description?.value)details.open=true;details.innerHTML='<summary>+ Registrar pedido y adelanto</summary>';card.prepend(details);details.append(form);card.querySelector('h2')?.remove();}
 const list=root.querySelector('#order-list');if(list){list.insertAdjacentHTML('beforebegin',`<div class="category-chips" aria-label="Agenda">${[['today','Hoy'],['tomorrow','Mañana'],['late','Atrasados'],['all','Todos']].map(([id,l])=>`<button type="button" data-agenda="${id}" class="${agenda===id?'selected':''}">${l}</button>`).join('')}</div>`);list.querySelectorAll('[data-order-row]').forEach((el,i)=>{const o=state().data.orders[i];el.dataset.orderRow=o.id;if(o.status==='pending')el.insertAdjacentHTML('beforeend',`<div class="actions"><button type="button" data-quick-order="${o.id}" data-section="order_payment" class="secondary">Cobrar</button><button type="button" data-quick-order="${o.id}" data-section="deliver_order" class="secondary">Entregar</button><button type="button" data-quick-order="${o.id}" data-section="upload_photos" class="secondary">Fotos</button></div>`);});filterAgenda();thumbnails();}}
 function countStatus(){
  const {shift,preview}=state();
  if(shift?.sales_mode!=='direct'||!preview)return '';
  return preview?.error?`<p class="warn">${esc(preview.error)}</p>`:`<p class="badge">Conteo guardado${shift.final_counted_at?' · '+esc(ctx.date(shift.final_counted_at)):''}</p>`;
 }
 const closingStep=()=>state().preview?.error?0:Math.min(3,Math.max(0,closing.step??(state().preview?1:0)));
 function closingView(){
  const {shift,canClose,preview}=state();
  if(!shift)return '<div class="warn">Esta tienda no tiene turno abierto.</div>';
  const step=canClose?closingStep():0,ready=!!preview&&!preview.error,cash=Number(closing.cash);
  const bag=Math.round((cash-200)*100)/100,diff=ready?Math.round((cash-Number(preview.expected_cash))*100)/100:null;
  let body='';
  if(step===0)body=`<h2>1. Contar productos</h2>${!canClose?'<p class="muted">Puedes guardar el conteo. El responsable del turno o un encargado asignado confirma la caja.</p>':''}<form data-form="final_counts" data-id="${esc(shift.id)}">${ctx.v2.countTable('final')}<label class="check"><input type="checkbox" required><span>Revisé los productos. Los campos vacíos equivalen a cero.</span></label><div class="actions">${canClose?'<button>Guardar y continuar a caja</button>':''}${shift.sales_mode==='direct'?'<button class="secondary" data-sell-after-count>Guardar y seguir vendiendo</button>':canClose?'':'<button>Guardar conteo</button>'}${canClose&&ready?'<button type="button" class="secondary" data-close-step="1">Usar conteo guardado</button>':''}</div></form>`;
  if(step===1)body=`<h2>2. Contar efectivo</h2>${ready?`<div class="summaryrow"><span>Efectivo esperado</span><strong>${money(preview.expected_cash)}</strong></div>`:''}<label>Efectivo contado, incluido sencillo (S/)<input data-closing-cash type="number" min="0" step=".01" value="${esc(closing.cash)}" inputmode="decimal"></label><details><summary>Ayuda por billetes y monedas</summary><div class="denominations">${[200,100,50,20,10,5,2,1,.5,.2,.1].map(n=>`<label>${money(n)}<input data-denomination="${n}" type="number" min="0" step="1" inputmode="numeric" placeholder="0"></label>`).join('')}</div><button type="button" class="secondary" data-cash-sum>Usar suma</button></details><button type="button" data-close-next>Continuar</button>`;
  if(step===2)body=`<h2>3. Separar sencillo y bolsa</h2><div class="summaryrow"><span>Efectivo contado</span><strong>${money(cash)}</strong></div><div class="summaryrow"><span>Sencillo para el siguiente turno</span><strong>${money(200)}</strong></div><div class="summaryrow total"><span>Dejar en bolsa</span><strong>${money(Math.max(0,bag))}</strong></div>${bag<0?'<p class="warn">No alcanza para dejar S/200 de sencillo. Revisa el conteo o registra el efectivo que falta antes de cerrar.</p>':'<button type="button" data-close-next>Revisar cierre</button>'}`;
  if(step===3)body=`<h2>4. Revisar y cerrar</h2>${!ready?`<p class="warn">${esc(preview?.error||'Primero guarda el conteo final.')}</p><button type="button" data-close-step="0">Revisar productos</button>`:`<div class="summaryrow"><span>Efectivo esperado</span><strong>${money(preview.expected_cash)}</strong></div><div class="summaryrow"><span>Efectivo contado</span><strong>${money(cash)}</strong></div><div class="summaryrow"><span>${diff===0?'Caja cuadra':diff<0?'Falta':'Sobra'}</span><strong>${money(Math.abs(diff))}</strong></div><p>${Number(preview.stock_variance_count||0)} productos con diferencias de stock.</p><form data-form="close_shift" data-id="${esc(shift.id)}"><input type="hidden" data-live-close-value name="inventory_revision" value="${esc(shift.inventory_revision??'')}"><input type="hidden" data-live-close-value name="reviewed_expected_cash" value="${esc(preview.expected_cash)}"><input type="hidden" data-live-close-value name="float_left" value="200"><input type="hidden" data-live-close-value name="bag_amount" value="${bag}"><label>Explicación de diferencias<textarea name="explanation" ${(diff!==0||Number(preview.stock_variance_count)>0)?'required':''}>${esc(closing.explanation)}</textarea></label><label class="check"><input type="checkbox" required><span>Confirmo el conteo, S/200 de sencillo y ${money(bag)} en bolsa.</span></label><button>Cerrar turno y guardar</button></form>`}`;
  return `<div class="card closing-wizard"><nav class="closing-steps" aria-label="Pasos del cierre">${['Productos','Efectivo','Sencillo','Revisión'].map((l,i)=>`<span class="${i===step?'selected':''}">${i+1}. ${l}</span>`).join('')}</nav>${step===3&&!ready?'':countStatus()}${body}${step>0?`<button type="button" class="secondary" data-close-back>${step===1?'Revisar conteo':'Volver al paso anterior'}</button>`:''}</div>`;
 }
 function validate(f){for(const el of f.querySelectorAll('[data-picker]')){const selected=el.querySelector('input[type=hidden]').value;if(!selected&&el.dataset.optional!=='true'){const q=el.querySelector('[data-picker-query]');q.setCustomValidity('Busca y elige un producto.');q.reportValidity();throw Error('Selecciona un producto de los resultados de búsqueda.');}}}
 async function click(b){if(b.dataset.pickerId){setPicker(b.closest('[data-picker]'),b.dataset.pickerId);persist();return true;}if(b.hasAttribute('data-picker-clear')){setPicker(b.closest('[data-picker]'),'');persist();return true;}if(b.hasAttribute('data-review-visible')){root.querySelectorAll('[data-stock-row]:not([hidden]) [data-reviewed]').forEach(e=>{reviewed[e.dataset.reviewed]=true;e.checked=true;});countProgress();persist();return true;}
 if(b.hasAttribute('data-close-step')){closing.step=Number(b.dataset.closeStep);ctx.render();return true;}if(b.hasAttribute('data-close-back')){closing.step=closingStep()-1;ctx.render();return true;}if(b.hasAttribute('data-close-next')){const step=closingStep();if(step===1&&(closing.cash===''||!Number.isFinite(Number(closing.cash))||Number(closing.cash)<0||Math.abs(Number(closing.cash)*100-Math.round(Number(closing.cash)*100))>1e-7))throw Error('Ingresa el efectivo contado con máximo dos decimales.');if(step===2){const id=state().shift?.id;b.disabled=true;try{await ctx.load();}finally{b.disabled=false;}if(id!==state().shift?.id||state().view!=='cierre'){ctx.render();return true;}}closing.step=step+1;ctx.render();return true;}if(b.hasAttribute('data-cash-sum')){let sum=0;for(const e of root.querySelectorAll('[data-denomination]')){if(!Number.isInteger(Number(e.value))||Number(e.value)<0)throw Error('Usa cantidades enteras de billetes y monedas.');sum+=Number(e.dataset.denomination)*Number(e.value);}closing.cash=String(Math.round(sum*100)/100);root.querySelector('[data-closing-cash]').value=closing.cash;persist();return true;}
 if(b.hasAttribute('data-agenda')){agenda=b.dataset.agenda;ctx.render();return true;}if(b.dataset.quickOrder){await ctx.v2.detail(b.dataset.quickOrder,({order_payment:'payments',deliver_order:'delivery',upload_photos:'photos'})[b.dataset.section]||'data');return true;}
 if(b.hasAttribute('data-discard-draft')){ctx.v2.clearCart();forms={};dirty.clear();status='Borrador vacío';ctx.render();return true;}return false;}
 function input(e){const t=e.target;if(t.hasAttribute('data-picker-query')&&e.type==='input'){const el=t.closest('[data-picker]');el.querySelector('input[type=hidden]').value='';t.setCustomValidity('');openPicker(el);}if(t.hasAttribute('data-picker-category'))pickerResults(t.closest('[data-picker]'));if(t.hasAttribute('data-unit-mode')){const span=t.closest('.unit-widget'),original=span.querySelector('input[name]'),proxy=span.querySelector('[data-pack-value]'),packs=t.value==='pack';proxy.value=original.value===''?'':String(Number(original.value)*2);proxy.hidden=!packs;proxy.required=packs&&original.required;original.type=packs?'hidden':'number';}if(t.hasAttribute('data-pack-value')){const original=t.closest('.unit-widget').querySelector('input[name]');original.value=t.value===''?'':String(Number(t.value)*.5);original.dispatchEvent(new Event('input',{bubbles:true}));}if(t.dataset.reviewed){reviewed[t.dataset.reviewed]=t.checked;countProgress();}if(t.closest('.inventory-table')&&t.name){reviewed[t.name]=true;const c=root.querySelector(`[data-reviewed="${t.name}"]`);if(c)c.checked=true;countProgress();}if(t.hasAttribute('data-closing-cash'))closing.cash=t.value;if(t.name==='explanation'&&t.closest('[data-form="close_shift"]'))closing.explanation=t.value;
 if(t.hasAttribute('data-catalog-search')&&e.type==='input'||t.hasAttribute('data-catalog-category')&&e.type==='change'){catalogQuery=root.querySelector('[data-catalog-search]').value;catalogCategory=root.querySelector('[data-catalog-category]').value;const box=root.querySelector('[data-catalog-results]');const items=state().data.products.filter(p=>(!catalogCategory||p.category===catalogCategory)&&norm(`${p.name} ${p.category} ${p.sku}`).includes(norm(catalogQuery)));box.innerHTML=catalogResults(items);}
 const f=t.closest('form[data-form]');if(f&&allowed(f))dirty.add(formKey(f));clearTimeout(timer);timer=setTimeout(persist,200);}
 function afterRender(){hydrate();attached=scope;attachedView=state().view;restoreForms();setupQuantities();setupCounts();setupOrders();ctx.v2.applyFilters();filterAgenda();paintStatus();persist();}
 root.addEventListener('focusin',e=>{if(e.target.hasAttribute('data-picker-query'))openPicker(e.target.closest('[data-picker]'));});root.addEventListener('keydown',e=>{const el=e.target.closest('[data-picker]');if(!el)return;if(e.key==='Escape'){el.querySelector('.picker-panel').hidden=true;e.target.setAttribute('aria-expanded','false');}if(e.key==='ArrowDown'){el.querySelector('[data-picker-id]')?.focus();e.preventDefault();}});document.addEventListener('click',e=>{if(!e.target.closest('[data-picker]'))root.querySelectorAll('.picker-panel').forEach(p=>p.hidden=true);});window.addEventListener('pagehide',persist);document.addEventListener('visibilitychange',()=>{if(document.hidden)persist();});
 return {discard:f=>{const id=formKey(f);delete forms[id];dirty.delete(id);delete f.dataset.request;delete f.dataset.payload;persist();},restoreDetail:()=>{restoreForms();setupQuantities();persist();},picker,catalog,click,input,validate,countStatus,afterRender,hydrate,flush,saving,committed,failed,closing:closingView,hasCart:()=>ctx.v2.snapshot().cart.length>0,countsSaved:()=>{reviewed={};for(const k of Object.keys(forms))if(k.includes('/final_counts/')){delete forms[k];dirty.delete(k);}closing={step:1,cash:'',explanation:''};},reset:()=>{scope='';attached='';forms={};dirty.clear();},statusHtml:()=>'<span class="save-status" data-save-status role="status">Borrador</span>'};
}
